"""Build searchable interactive-agenda pages for archived packets."""
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MEETINGS = {
    "2025-11-18": ("November 18, 2025", "BI_NOVEMBER_18_2025_SOURCES"),
    "2025-12-02": ("December 2, 2025", "BI_DECEMBER_2_2025_SOURCES"),
    "2025-12-16": ("December 16, 2025", "BI_DECEMBER_16_2025_SOURCES"),
    "2026-01-20": ("January 20, 2026", "BI_JANUARY_20_SOURCES"),
    "2026-02-03": ("February 3, 2026", "BI_FEBRUARY_3_SOURCES"),
    "2026-02-17": ("February 17, 2026", "BI_FEBRUARY_17_SOURCES"),
    "2026-02-23": ("February 23, 2026", "BI_FEBRUARY_23_SOURCES"),
    "2026-03-03": ("March 3, 2026", "BI_MARCH_3_SOURCES"),
    "2026-09-15": ("September 15, 2026", "BI_SEPTEMBER_15_SOURCES"),
}

PAGE = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{label} Interactive Agenda | Beaumont Intelligence</title><link href="../favicon.png" rel="icon"><link href="../styles.css" rel="stylesheet"><style>
.agenda-toolbar{{display:grid;grid-template-columns:1fr 220px;gap:12px;margin:22px 0}}.agenda-toolbar input,.agenda-toolbar select{{width:100%;padding:13px;border:1px solid var(--line);border-radius:10px;font:inherit}}.agenda-section{{margin:24px 0}}.agenda-section>h2{{border-bottom:3px solid var(--blue);padding-bottom:9px}}.agenda-record{{margin:12px 0;border:1px solid var(--line);border-radius:12px;background:#fff;overflow:hidden}}.agenda-record summary{{cursor:pointer;display:grid;grid-template-columns:70px 1fr auto;gap:14px;align-items:center;padding:16px 18px;list-style:none}}.agenda-record summary:after{{content:'+';font-size:1.5rem;font-weight:800;color:var(--blue)}}.agenda-record[open] summary:after{{content:'−'}}.agenda-number{{font-weight:900;color:var(--red)}}.agenda-title{{font-weight:850;color:var(--blue)}}.agenda-documents{{border-top:1px solid var(--line);padding:6px 18px 14px}}.agenda-document{{display:grid;grid-template-columns:1fr auto;gap:14px;align-items:center;padding:11px 0;border-bottom:1px solid var(--line)}}.viewer-dialog{{width:min(1180px,96vw);height:92vh;border:0;border-radius:14px;padding:0}}.viewer-dialog::backdrop{{background:#001b3dcc}}.viewer-dialog header{{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 16px}}.viewer-dialog iframe{{display:block;width:100%;height:calc(92vh - 58px);border:0}}@media(max-width:650px){{.agenda-toolbar,.agenda-record summary,.agenda-document{{grid-template-columns:1fr}}}}
</style></head><body><a class="skip-link" href="#main">Skip to content</a><div class="preview-banner"><strong>Archived interactive agenda</strong><span>{label} · complete voting calendars</span></div><header class="app-header"><div class="wrap header-row"><a class="brand" href="../index.html"><img class="brand-logo" src="../mbf-logo.png" alt=""><span class="brand-copy"><strong><span class="red">BEAUMONT</span> <span class="blue">INTELLIGENCE</span></strong><small>Council Intelligence</small></span></a></div></header><main id="main"><section class="section compact"><div class="wrap narrow"><div class="eyebrow">{label}</div><h1>Interactive council agenda</h1><p class="lead-copy">Browse the Public Hearing, Action, and Consent calendars. Expand an item, then open any staff report or attachment without leaving this page.</p><div class="status-actions"><a class="btn" href="{date}.html">← Return to briefing</a><a class="btn secondary" href="../council-meeting-sources.html">Available agenda sources</a><button class="btn secondary" id="packet-button" type="button">Full agenda packet</button></div><div class="agenda-toolbar"><input id="source-search" type="search" placeholder="Search agenda items and attachments…"><select id="source-section"><option value="all">All voting calendars</option><option>Public Hearing</option><option>Action</option><option>Consent</option></select></div><p id="source-count"></p><div id="source-results"></div></div></section></main><dialog class="viewer-dialog" id="viewer-dialog"><header><strong id="viewer-title">Document viewer</strong><button class="btn small" id="viewer-close" type="button">Close ×</button></header><iframe id="viewer-frame" title="Document viewer"></iframe></dialog><script src="{date}-sources.js"></script><script>
(()=>{{const DATA=window.{variable},ORDER=['Public Hearing','Action','Consent'],q=document.querySelector('#source-search'),f=document.querySelector('#source-section'),out=document.querySelector('#source-results'),count=document.querySelector('#source-count'),dialog=document.querySelector('#viewer-dialog'),frame=document.querySelector('#viewer-frame'),viewerTitle=document.querySelector('#viewer-title');function esc(v){{return String(v).replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]))}}function itemTitle(files){{const staff=files.find(x=>/staff report/i.test(x.title))||files[0];return staff.title.replace(/^staff report\s*[-–:]?\s*/i,'')}}function openViewer(url,title){{viewerTitle.textContent=title;const back=new URL('{date}-sources.html',location.href).href;frame.src=`../documents/viewer.html?url=${{encodeURIComponent(url)}}&title=${{encodeURIComponent(title)}}&returnUrl=${{encodeURIComponent(back)}}&returnLabel=${{encodeURIComponent('Back to interactive agenda')}}`;dialog.showModal()}}function closeViewer(){{dialog.close();frame.src='about:blank'}}function render(){{const term=q.value.toLowerCase().trim(),docs=DATA.filter(x=>(f.value==='all'||x.section===f.value)&&(!term||`${{x.item}} ${{x.title}}`.toLowerCase().includes(term)));count.textContent=`Showing ${{docs.length}} of ${{DATA.length}} voting-calendar documents`;out.innerHTML=ORDER.map(section=>{{const sectionDocs=docs.filter(x=>x.section===section);if(!sectionDocs.length)return'';const groups=Object.groupBy(sectionDocs,x=>x.item);return `<section class="agenda-section"><h2>${{esc(section)}} calendar</h2>${{Object.entries(groups).map(([item,files])=>`<details class="agenda-record" ${{term?'open':''}}><summary><span class="agenda-number">${{esc(item)}}</span><span class="agenda-title">${{esc(itemTitle(files))}}</span></summary><div class="agenda-documents">${{files.map(d=>`<div class="agenda-document"><span>${{esc(d.title)}}</span><button class="btn small" data-url="${{esc(d.archiveUrl)}}" data-title="${{esc(d.title)}}">View document</button></div>`).join('')}}</div></details>`).join('')}}</section>`}}).join('')||'<div class="empty">No agenda documents match.</div>'}}out.addEventListener('click',e=>{{const b=e.target.closest('[data-url]');if(b)openViewer(b.dataset.url,b.dataset.title)}});q.addEventListener('input',render);f.addEventListener('change',render);document.querySelector('#viewer-close').addEventListener('click',closeViewer);document.querySelector('#packet-button').addEventListener('click',()=>openViewer('https://documents.beaumontintelligence.com/records/agenda-packets/{date}/{date}-city-council-agenda-package.pdf','{label} agenda packet'));render()}})();
</script></body></html>"""

parser = argparse.ArgumentParser()
parser.add_argument("--meeting", action="append", choices=sorted(MEETINGS))
args = parser.parse_args()
selected = set(args.meeting or MEETINGS)

for date, (label, variable) in MEETINGS.items():
    if date not in selected:
        continue
    (ROOT / "docs" / "briefings" / f"{date}-sources.html").write_text(
        PAGE.format(date=date, label=label, variable=variable), encoding="utf-8"
    )
    print(f"Built {date} interactive agenda")
